export interface KnownPartRole {
  id: KnownPartRoleId
  component: string
  label: string
  selectors: Array<{ selector: string; localSelector?: string }>
  source?: 'native-aware' | 'dom-scoped'
  overrideStrength?: 'normal' | 'strong'
}

export interface CommonPartCategory {
  id: CommonPartCategoryId
  label: string
  component: string
  description: string
  icon: string
}

export interface CommonPresetStep {
  role: KnownPartRoleId
  label?: string
  primary?: boolean
  createPackets: () => StylePacket[]
  /** Optional phone-only delta. Stored and reset with the same recipe provenance as Base. */
  createMobilePackets?: () => StylePacket[]
  /** Keep authored text colors instead of remapping Text Style packets through the quick/pack palette. */
  tuneText?: boolean
}

export interface CommonPresetGroupStep {
  id: string
  name: string
  parentRole: KnownPartRoleId
  memberRoles: KnownPartRoleId[]
  base: LayoutGroupState
  mobile?: LayoutGroupState
  createStyles?: () => LayoutGroupStyles
}

export interface CommonPartPreset {
  id: string
  category: CommonPartCategoryId
  name: string
  description: string
  preview: CommonPresetPreview
  /** Stable gallery grouping; recipes can grow without regex-based UI archaeology. */
  section?: string
  steps: CommonPresetStep[]
  /** Optional virtual sibling compositions. Packs can now ship layout groups without DOM wrappers. */
  groups?: CommonPresetGroupStep[]
}

function packet<T extends StylePacket['type']>(type: T): Extract<StylePacket, { type: T }> {
  return createStylePacket(type) as Extract<StylePacket, { type: T }>
}

export function textInkModeForRole(role: KnownPartRoleId): 'cascade' | 'force' {
  // Composer controls are the proven hostile zone: Lumi can own -webkit-text-fill-color.
  // Elsewhere ordinary CSS color is preferable because descendant font/dialogue markup must remain free to override it.
  return role.startsWith('input.') ? 'force' : 'cascade'
}

export function applyTextInkPolicyForRole(role: KnownPartRoleId, packets: StylePacket[]): StylePacket[] {
  const inkMode = textInkModeForRole(role)
  return packets.map((entry) => entry.type === 'text' && entry.colorMode === 'solid' ? { ...entry, inkMode } : entry)
}


