const EDITORIAL_THOUGHT_MARK = 'data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22M12%204%2020%2012%2012%2020%204%2012%2012%204Z%22%20fill%3D%22none%22%20stroke%3D%22%2392a6b3%22%20stroke-width%3D%221.6%22%2F%3E%3Cpath%20d%3D%22M8.5%2012h7%22%20stroke%3D%22%2392a6b3%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%2F%3E%3C%2Fsvg%3E'

function ornamentPath(id: string): string { return builtinOrnament(id)?.assetPath ?? '' }

function ornamentPlanePackets(id: string, color: string, width: number, height: number, anchorRole: KnownPartRoleId, offsets: { top?: number; right?: number; bottom?: number; left?: number; zIndex?: number } = {}, alpha = 1): StylePacket[] {
  const background = packet('background'); background.mode = 'image'; background.image.assetPath = ornamentPath(id); background.image.size = 'contain'; background.image.positionX = 50; background.image.positionY = 50; background.image.repeat = 'no-repeat'; background.image.renderMode = 'mask'; background.image.maskColor = color; background.image.maskAlpha = alpha; background.image.hideContents = false
  const position = packet('position'); position.mode = 'anchored'; position.anchorSelector = KNOWN_PART_ROLES[anchorRole].selectors[0].selector.replace(/::(?:before|after)$/, ''); position.anchorLabel = KNOWN_PART_ROLES[anchorRole].label; position.unit = 'px'; position.layer = 'custom'; position.zIndex = offsets.zIndex ?? 20; position.top = offsets.top; position.right = offsets.right; position.bottom = offsets.bottom; position.left = offsets.left
  const size = packet('size'); size.width = { mode: 'fixed', value: width, unit: 'px' }; size.height = { mode: 'fixed', value: height, unit: 'px' }
  return [background, position, size]
}

function ornamentSvgSource(id: string): string {
  const assetPath = ornamentPath(id)
  const prefix = 'data:image/svg+xml,'
  if (!assetPath.startsWith(prefix)) return ''
  try { return decodeURIComponent(assetPath.slice(prefix.length)) } catch { return '' }
}

function ornamentSvgPlanePackets(id: string, color: string, width: number, height: number, anchorRole: KnownPartRoleId, offsets: { top?: number; right?: number; bottom?: number; left?: number; zIndex?: number } = {}, alpha = 1): StylePacket[] {
  const svg = packet('svg-asset'); svg.svg = ornamentSvgSource(id); svg.assetName = builtinOrnament(id)?.label; svg.renderMode = 'mask'; svg.color = color; svg.alpha = alpha; svg.fit = 'contain'; svg.positionX = 50; svg.positionY = 50
  const position = packet('position'); position.mode = 'anchored'; position.anchorSelector = KNOWN_PART_ROLES[anchorRole].selectors[0].selector.replace(/::(?:before|after)$/, ''); position.anchorLabel = KNOWN_PART_ROLES[anchorRole].label; position.unit = 'px'; position.layer = 'custom'; position.zIndex = offsets.zIndex ?? 20; position.top = offsets.top; position.right = offsets.right; position.bottom = offsets.bottom; position.left = offsets.left
  const size = packet('size'); size.width = { mode: 'fixed', value: width, unit: 'px' }; size.height = { mode: 'fixed', value: height, unit: 'px' }
  return [svg, position, size]
}

function thoughtMarkPackets(assetPath: string, sizeValue: number, color: string): StylePacket[] {
  const background = packet('background'); background.mode = 'image'; background.image.assetPath = assetPath; background.image.size = 'contain'; background.image.positionX = 50; background.image.positionY = 50; background.image.repeat = 'no-repeat'; background.image.renderMode = 'mask'; background.image.maskColor = color; background.image.maskAlpha = 1; background.image.hideContents = true
  const size = packet('size'); size.width = { mode: 'fixed', value: sizeValue, unit: 'px' }; size.height = { mode: 'fixed', value: sizeValue, unit: 'px' }
  return [background, size]
}

function mediaFlowPackets(mode: 'natural' | 'full' = 'full', unclipped = true): StylePacket[] {
  const flow = packet('media-flow'); flow.mode = mode; flow.unclipped = unclipped
  return [flow]
}

function vnHeartPackets(sizeValue: number, color: string, alpha = 1): StylePacket[] {
  const background = packet('background'); background.mode = 'image'; background.image.assetPath = ornamentPath('scribble-heart'); background.image.size = 'contain'; background.image.positionX = 50; background.image.positionY = 50; background.image.repeat = 'no-repeat'; background.image.renderMode = 'mask'; background.image.maskColor = color; background.image.maskAlpha = alpha; background.image.hideContents = false
  const size = packet('size'); size.width = { mode: 'fixed', value: sizeValue, unit: 'px' }; size.height = { mode: 'fixed', value: Math.max(8, Math.round(sizeValue * .86)), unit: 'px' }
  return [background, size]
}

function vnActionTextPackets(label: string, color = '#f4eef8'): StylePacket[] {
  const content = packet('content'); content.source = 'literal'; content.value = label
  const typography = packet('typography'); typography.fontFamily = 'Trebuchet MS, ui-sans-serif, system-ui, sans-serif'; typography.fontSize = 8.2; typography.fontWeight = 800; typography.transform = 'uppercase'; typography.letterSpacing = .35; typography.lineHeight = 1
  const text = packet('text'); text.inkMode = 'force'; text.solid = { color, alpha: .96 }; text.outlineMode = 'outside'; text.strokeWidth = .8; text.strokeColor = '#332b5f'; text.strokeAlpha = .92
  return [content, typography, text]
}

function vnArrowPackets(id: 'vn-arrow-left' | 'vn-arrow-right'): StylePacket[] {
  const background = packet('background'); background.mode = 'image'; background.image.assetPath = ornamentPath(id); background.image.size = 'contain'; background.image.positionX = 50; background.image.positionY = 50; background.image.repeat = 'no-repeat'; background.image.renderMode = 'mask'; background.image.maskColor = '#e4f6f9'; background.image.maskAlpha = .86; background.image.hideContents = true
  const border = packet('border'); border.width = 0
  const size = packet('size'); size.width = { mode: 'fixed', value: 22, unit: 'px' }; size.height = { mode: 'fixed', value: 16, unit: 'px' }
  return [background, border, size]
}

function vnStageEdgePackets(anchorRole: KnownPartRoleId, color: string, alpha: number, edge: 'top' | 'bottom', mobile = false): StylePacket[] {
  const background = packet('background'); background.mode = 'image'; background.image.assetPath = ornamentPath(mobile ? 'vn-mobile-corners' : 'vn-wide-corners'); background.image.size = 'contain'; background.image.positionX = 50; background.image.positionY = 0; background.image.repeat = 'no-repeat'; background.image.renderMode = 'mask'; background.image.maskColor = color; background.image.maskAlpha = alpha; background.image.hideContents = false
  const position = packet('position'); position.mode = 'anchored'; position.anchorSelector = KNOWN_PART_ROLES[anchorRole].selectors[0].selector.replace(/::(?:before|after)$/, ''); position.anchorLabel = KNOWN_PART_ROLES[anchorRole].label; position.left = mobile ? 6 : 10; position.right = mobile ? 6 : 10; position.unit = 'px'; position.layer = 'custom'; position.zIndex = 4; if (edge === 'top') position.top = mobile ? 5 : 7; else position.bottom = mobile ? 5 : 7
  const size = packet('size'); size.width = { mode: 'parent' }; size.height = { mode: 'fixed', value: mobile ? 54 : 64, unit: 'px' }
  const packets: StylePacket[] = [background, position, size]
  if (edge === 'bottom') { const transform = packet('transform'); transform.rotate = 180; packets.push(transform) }
  return packets
}

interface HeroCompositionOptions {
  height: number
  focusX: number
  focusY: number
  fadeAmount: number
  metaBottom?: number
  align?: 'start' | 'center' | 'end'
  sidePadding?: number
  nameSize?: number
  nameTracking?: number
}

/**
 * A hero treatment is a composition, not an avatar-size trick.  Keep the
 * mechanics in one helper so every hero preset establishes the same safe
 * containing plane, full-frame image, and readable metadata layer.
 */
function heroCompositionSteps(options: HeroCompositionOptions): CommonPresetStep[] {
  const align = options.align ?? 'center'
  const sidePadding = options.sidePadding ?? (align === 'center' ? 0 : 24)
  return [
    { role: 'header.root', createPackets: () => {
      const size = packet('size'); size.minHeight = { mode: 'fixed', value: options.height + 20, unit: 'px' }
      return [size]
    } },
    { role: 'header.left', createPackets: () => {
      const size = packet('size'); size.width = { mode: 'parent' }
      const layout = packet('layout'); layout.display = 'flex'; layout.direction = 'column'; layout.align = 'center'; layout.justify = 'end'; layout.gap = { mode: 'fixed', value: 0, unit: 'px' }
      return [layout, size]
    } },
    { role: 'avatar.frame', primary: true, createPackets: () => {
      const position = packet('position'); position.mode = 'anchored'; position.anchorSelector = KNOWN_PART_ROLES['header.root'].selectors[0].selector; position.anchorLabel = 'Header'; position.top = 0; position.right = 0; position.left = 0; position.unit = 'px'; position.layer = 'custom'; position.zIndex = 1
      const size = packet('size'); size.width = { mode: 'parent' }; size.height = { mode: 'fixed', value: options.height, unit: 'px' }
      const corners = packet('corners'); corners.topLeft = corners.topRight = corners.bottomRight = corners.bottomLeft = 0
      return [position, size, corners]
    } },
    { role: 'avatar.image', createPackets: () => {
      const image = packet('image'); image.sourceQuality = 'auto'; image.objectFit = 'cover'; image.fillFrame = true; image.objectPositionX = options.focusX; image.objectPositionY = options.focusY; image.fade = { direction: 'bottom', amount: options.fadeAmount }
      return [image]
    } },
    { role: 'meta.row', createPackets: () => {
      const position = packet('position'); position.mode = 'anchored'; position.anchorSelector = KNOWN_PART_ROLES['header.root'].selectors[0].selector; position.anchorLabel = 'Header'; position.right = sidePadding; position.bottom = options.metaBottom ?? 12; position.left = sidePadding; position.unit = 'px'; position.layer = 'custom'; position.zIndex = 10
      const size = packet('size'); size.width = { mode: 'parent' }
      const layout = packet('layout'); layout.display = 'flex'; layout.direction = 'column'; layout.align = align; layout.justify = 'end'; layout.gap = { mode: 'fixed', value: 5, unit: 'px' }
      return [position, size, layout]
    } },
    { role: 'name.character', createPackets: () => {
      const typography = packet('typography'); typography.fontFamily = 'Georgia'; typography.fontSize = options.nameSize ?? 27; typography.fontWeight = 700; typography.lineHeight = 1; typography.letterSpacing = options.nameTracking ?? 1.2; typography.textAlign = align === 'start' ? 'left' : align === 'end' ? 'right' : 'center'
      const text = packet('text'); text.solid = { color: '#f4eef8', alpha: 1 }; text.shadow = { x: 0, y: 2, blur: 16, color: '#000000', alpha: .52 }
      return [typography, text]
    } },
    { role: 'meta.pill', createPackets: () => {
      const background = packet('background'); background.solid = { color: '#000000', alpha: .72 }
      const corners = packet('corners'); corners.topLeft = corners.topRight = corners.bottomRight = corners.bottomLeft = 999
      const spacing = packet('spacing'); spacing.padding = { linked: false, top: 4, right: 9, bottom: 4, left: 9, unit: 'px' }
      const item = packet('layout-item'); item.alignSelf = align
      return [background, corners, spacing, item]
    } },
  ]
}

