export function targetForKnownRole(roleId: KnownPartRoleId): StudioTarget {
  const role = KNOWN_PART_ROLES[roleId]
  let candidate = role.selectors[0]
  if (typeof document !== 'undefined') {
    const mounted = role.selectors.find((entry) => { try { return Boolean(document.querySelector(entry.selector)) } catch { return false } })
    if (mounted) candidate = mounted
  }
  return {
    selector: candidate.selector,
    strategy: 'studio-registry',
    stability: 'high',
    persistence: 'persistent',
    source: role.source ?? 'native-aware',
    label: role.label,
    nativeContextSelector: role.source === 'dom-scoped' ? undefined : `[data-component="${role.component}"]`,
    localSelector: candidate.localSelector,
    overrideStrength: role.overrideStrength ?? 'strong',
  }
}

