function ledgerSegmentPackets(accent: string): StylePacket[] {
  // The segment stays native data inside the real meta pill. The cell treatment is
  // deliberately quiet so the identity/name remains the hero instead of becoming
  // three tiny specimen boxes.
  const layout = packet('layout'); layout.display = 'flex'; layout.direction = 'column'; layout.align = 'start'; layout.justify = 'end'; layout.gap = { mode: 'fixed', value: 1, unit: 'px' }
  const spacing = packet('spacing'); spacing.padding = { linked: false, top: 14, right: 10, bottom: 6, left: 10, unit: 'px' }
  const background = packet('background'); background.solid = { color: accent, alpha: .055 }
  const border = packet('border'); border.width = 0; border.color = accent; border.alpha = 0
  const corners = packet('corners'); corners.topLeft = corners.topRight = corners.bottomRight = corners.bottomLeft = 3
  const typography = packet('typography'); typography.fontFamily = 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace'; typography.fontSize = 10; typography.fontWeight = 760; typography.letterSpacing = .22
  const text = packet('text'); text.solid = { color: '#3d4946', alpha: .96 }
  return [layout, spacing, background, border, corners, typography, text]
}
function ledgerLabelPackets(label: string, accent: string): StylePacket[] {
  const content = packet('content'); content.value = label
  const typography = packet('typography'); typography.fontFamily = 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace'; typography.fontSize = 6.5; typography.fontWeight = 900; typography.letterSpacing = 1.05
  const text = packet('text'); text.solid = { color: accent, alpha: .96 }
  // This target is already a pseudo-surface on the live metadata segment. Anchored
  // positioning is local to that generated plane; do not invent a second DOM anchor.
  const position = packet('position'); position.mode = 'anchored'; position.top = 3; position.left = 10; position.unit = 'px'; position.layer = 'custom'; position.zIndex = 2
  const size = packet('size'); size.width = { mode: 'content' }; size.height = { mode: 'content' }
  return [content, typography, text, position, size]
}

