export function presetRoles(preset: CommonPartPreset): KnownPartRole[] {
  const ids = [...preset.steps.map((step) => step.role), ...(preset.groups ?? []).flatMap((group) => [group.parentRole, ...group.memberRoles])]
  return [...new Set(ids)].map((id) => KNOWN_PART_ROLES[id])
}
